package models

// Patch describes a textual edit to a flow's source text. Edits are LINE-BASED
// (1-based, matching Block.LineNumber) and apply to the RAW source text —
// never a re-serialization (which would lose PAD's original parameter order,
// quoting and multi-line values); the result is re-parsed and re-analyzed.
// Patches are intentionally minimal and structural, generated by AutoFixers
// and reviewed by the user before apply.
type Patch struct {
	// File is the source file within a multi-file flow ("" for single-file); patches target one file.
	File string    `json:"file,omitempty"`
	Ops  []PatchOp `json:"ops"`
}

// PatchOp is one line-level textual edit; the Kind discriminates the op, and
// only the fields relevant to that kind are set.
//
// Kind "insert": insert Lines before BeforeLine (1-based); 0 or beyond EOF
// appends; multiple inserts apply bottom-up so earlier ops don't shift later
// targets.
//
// Kind "wrap": wrap [StartLine..EndLine] with Header and Footer, re-indenting
// by IndentDelta levels (ON BLOCK ERROR … END: header/footer at the block's
// indent, wrapped lines one level in as the handler's children).
//
// Kind "append": append Lines[0] to the end of line StartLine — adds a
// property in-place (e.g. ` Timeout: 30`), preserving parameter order,
// quoting and multi-line values.
//
// Kind "replace": within line StartLine, replace occurrences of Old with New
// (swap a hardcoded literal for a %Variable% reference in-place).
//
// Kind "remove": delete [StartLine..EndLine] — a block and its descendants;
// same range semantics as "wrap" without header/footer.
type PatchOp struct {
	Kind       string   `json:"kind"`
	BeforeLine int      `json:"beforeLine,omitempty"`
	Lines      []string `json:"lines,omitempty"`
	// wrap + append + replace
	StartLine   int    `json:"startLine,omitempty"`
	EndLine     int    `json:"endLine,omitempty"`
	Header      string `json:"header,omitempty"`
	Footer      string `json:"footer,omitempty"`
	IndentDelta int    `json:"indentDelta,omitempty"`
	// replace
	Old string `json:"old,omitempty"`
	New string `json:"new,omitempty"`
	// Property anchors a replace to one `Key: value` pair on the line; without
	// it the replace is a whole-line ReplaceAll (replacing "50" for property X
	// also rewrote the "Order 1050" window title). Empty keeps the unanchored
	// behaviour, correct for values carrying their own delimiters.
	Property string `json:"property,omitempty"`
}
